<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{stage10Api}from'@/api/stage10'
const rules=ref<any[]>([]),alerts=ref<any[]>([]),selected=ref<any>(),open=ref(false),busy=ref(false),form=reactive({name:'',rule_type:'keyword',severity:'warning',value:'',combinator:'all'});const types:any={keyword:'关键词',heat:'热度',negative:'负面占比',media:'指定媒体',official:'官方内容',velocity:'传播速度',ai_risk:'AI 风险',composite:'组合规则'};const states:any={triggered:'待确认',acknowledged:'已确认',resolved:'已处置',closed:'已关闭'}
function config(){if(form.rule_type==='keyword')return{keywords:form.value.split(/[,，]/).filter(Boolean)};if(form.rule_type==='media')return{sources:form.value.split(/[,，]/).filter(Boolean)};if(form.rule_type==='negative')return{ratio:Number(form.value||40)/100};if(form.rule_type==='velocity')return{per_hour:Number(form.value||5)};if(form.rule_type==='official')return{min_count:Number(form.value||1)};if(form.rule_type==='composite')return{conditions:[{type:'keyword',keywords:form.value.split(/[,，]/).filter(Boolean)},{type:'ai_risk',min:60}]};return{min:Number(form.value||60)}}async function load(){[rules.value,alerts.value]=await Promise.all([stage10Api.rules(),stage10Api.alerts()]);if(selected.value)selected.value=await stage10Api.alert(selected.value.id)}async function create(){await stage10Api.createRule({name:form.name,rule_type:form.rule_type,severity:form.severity,combinator:form.combinator,config:config(),enabled:true});open.value=false;await load()}async function run(r:any){busy.value=true;try{const x=await stage10Api.runRule(r.id);ElMessage.success(`扫描完成，命中 ${x.matched_count} 个事件`);await load()}finally{busy.value=false}}async function replay(r:any){const to=new Date(),from=new Date(Date.now()-30*86400000);const x=await stage10Api.replay(r.id,{from_at:from.toISOString(),to_at:to.toISOString()});ElMessage.success(`历史回放命中 ${x.matched_count} 个事件，未创建预警`)}async function act(action:string){if(!selected.value)return;const note=await ElMessageBox.prompt('处置说明','更新预警',{inputValue:''});await stage10Api.act(selected.value.id,{action,note:note.value,assignee_id:null});await load()}async function remove(r:any){await ElMessageBox.confirm(`删除规则“${r.name}”？`,'删除规则',{confirmButtonText:'删除规则',type:'warning'});await stage10Api.removeRule(r.id);await load()}onMounted(load)
</script>
<template><main><header><div><small>ALERT OPERATIONS</small><h1>预警中心</h1><p>从真实事件触发预警，完成确认、分派、处置、关闭和误报反馈。</p></div><button class="primary" @click="open=true"><el-icon><Plus/></el-icon>新建规则</button></header><section class="layout"><div class="rules"><h2>监控规则</h2><article v-for="r in rules" :key="r.id"><div><span>{{types[r.rule_type]}}</span><strong>{{r.name}}</strong><small>{{r.combinator.toUpperCase()}} · {{r.severity}}</small></div><button title="历史回放" @click="replay(r)"><el-icon><Clock/></el-icon></button><button title="立即扫描" :disabled="busy" @click="run(r)"><el-icon><VideoPlay/></el-icon></button><button title="删除" @click="remove(r)"><el-icon><Delete/></el-icon></button></article><div v-if="!rules.length" class="empty">尚无预警规则</div></div><div class="incidents"><h2>预警队列</h2><button v-for="a in alerts" :key="a.id" :class="{active:selected?.id===a.id}" @click="stage10Api.alert(a.id).then(x=>selected=x)"><i :class="a.severity"/><span><strong>{{a.title}}</strong><small>{{a.reason}}</small></span><em>{{states[a.status]}}</em></button><div v-if="!alerts.length" class="empty">当前没有真实预警</div></div><aside><template v-if="selected"><span :class="`badge ${selected.severity}`">{{selected.severity}}</span><h2>{{selected.title}}</h2><p>{{selected.reason}}</p><dl><div><dt>状态</dt><dd>{{states[selected.status]}}</dd></div><div><dt>证据</dt><dd>{{selected.evidence.length}} 条</dd></div><div><dt>负责人</dt><dd>{{selected.assignee_id||'未分派'}}</dd></div></dl><div class="actions"><button @click="act('acknowledge')">确认</button><button @click="act('resolve')">标记已处置</button><button @click="act('close')">关闭</button><button class="danger" @click="act('false_positive')">标记误报</button></div><h3>处置记录</h3><article v-for="x in selected.actions" :key="x.id" class="log"><span>{{x.action}}</span><small>{{x.note||'无说明'}}</small></article></template><div v-else class="empty">选择预警查看处置详情</div></aside></section><el-dialog v-model="open" title="新建预警规则" width="min(520px,92%)"><div class="form"><label>规则名称<input v-model="form.name"/></label><label>规则类型<select v-model="form.rule_type"><option v-for="(v,k) in types" :key="k" :value="k">{{v}}</option></select></label><label>阈值 / 关键词 / 来源<input v-model="form.value" :placeholder="form.rule_type==='keyword'?'多个关键词用逗号分隔':'输入阈值'"/></label><label>严重程度<select v-model="form.severity"><option>info</option><option>warning</option><option>critical</option></select></label><label v-if="form.rule_type==='composite'">组合方式<select v-model="form.combinator"><option value="all">全部满足</option><option value="any">任一满足</option></select></label></div><template #footer><button @click="open=false">取消</button><button class="primary" @click="create">创建规则</button></template></el-dialog></main></template>
<style scoped>main{padding:30px;min-height:100vh;background:#f5f7f8;color:#17211d}main>header{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px}h1{margin:4px 0}header p{margin:0;color:#6e7874}header small{color:#a64a42;font-weight:800}.primary,.actions button{border:0;border-radius:5px;padding:10px 14px;color:white;background:#176f67}.layout{display:grid;grid-template-columns:320px 1fr 330px;min-height:650px;background:white;border:1px solid #dce3e0}.layout>div,.layout>aside{padding:16px;border-right:1px solid #e0e6e3}.rules article{display:grid;grid-template-columns:1fr 32px 32px 32px;gap:5px;padding:12px 0;border-bottom:1px solid #e5e9e7}.rules article div{display:flex;flex-direction:column}.rules article span{color:#a64a42;font-size:10px}.rules button{border:0;background:none}.incidents>button{width:100%;display:grid;grid-template-columns:6px 1fr auto;gap:10px;padding:13px 8px;border:0;border-bottom:1px solid #e5e9e7;background:none;text-align:left}.incidents>button.active{background:#eef5f3}.incidents i{height:100%;background:#e1a743}.incidents i.critical{background:#d95751}.incidents span{display:flex;flex-direction:column}.incidents small{color:#75807b}.incidents em{font-style:normal;font-size:11px}.badge{padding:4px 7px;background:#fff0d2}.badge.critical{color:#aa322d;background:#fae6e4}dl div{display:flex;justify-content:space-between;padding:9px;border-bottom:1px solid #eee}dd{margin:0}.actions{display:flex;flex-wrap:wrap;gap:6px}.actions .danger{background:#b9423b}.log{display:flex;justify-content:space-between;padding:9px;border-bottom:1px solid #eee}.empty{padding:50px 12px;text-align:center;color:#7a8580}.form{display:grid;gap:13px}.form label{display:grid;gap:5px}.form input,.form select{height:38px;border:1px solid #ccd6d2;padding:0 9px}@media(max-width:1100px){.layout{grid-template-columns:280px 1fr}.layout>aside{grid-column:1/-1;border-top:1px solid #ddd}}@media(max-width:720px){main{padding:76px 12px 20px}header p{display:none}.layout{display:block}.layout>div,.layout>aside{border-right:0;border-bottom:1px solid #ddd}}</style>
